  "translations": {
    "L0001": "The proofreader set two headings side by side.",
    "L0002": "On one, they wrote “Letter”.",
    "L0003": "On the other, they wrote “我在等你” (“I’m waiting for you”).",
    "L0004": "Not translations, but separate quotations.",
    "L0005": "They did not erase the “OK” in the margin.",
    "L0006": "Neither letter has arrived yet."
  },
